commands.scriptSource:
import assert from 'node:assert/strict';
import { readFileSync, existsSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { resolve } from 'node:path';
const repo = 'E:/cs2-analyst';
const work = 'C:/Users/evanpatchouli/Documents/Codex/2026-10-26/files-pasted-by-the-user-p8/work';
const record = JSON.parse(readFileSync(resolve(repo, 'docs/p8-1l2-spatial-benchmark-2026-10-26.json')));
const markdown = readFileSync(resolve(repo, 'docs/p8-1l2-spatial-benchmark-2026-10-26.md'), 'utf8');
const original = JSON.parse(readFileSync(resolve(work, 'spatial-benchmark-run.json')));
const frozen = JSON.parse(readFileSync(resolve(work, 'spatial-protocol-frozen.json')));
const sha = bytes => createHash('sha256').update(bytes).digest('hex');
function subset(actual, expected) {
  if (expected === null || typeof expected !== 'object') return assert.deepEqual(actual, expected);
  if (Array.isArray(expected)) assert.equal(actual.length, expected.length);
  for (const key of Object.keys(expected)) subset(actual[key], expected[key]);
}
const groups = [];
for (const [key, value] of Object.entries(original)) if (key !== 'probes') subset(record.execution[key], value);
assert.ok(!Object.hasOwn(record.execution, 'probes')); groups.push('all persisted execution values match original scratch result; raw probes omitted');
assert.equal(sha(readFileSync(resolve(repo, 'docs/experiments/p8-1l2-spatial-benchmark.mjs'))), frozen.scriptSha256);
assert.equal(record.freeze.protocolSha256, frozen.protocolSha256);
assert.ok(Date.parse(frozen.frozenAt) < Date.parse(record.execution.startedAt)); groups.push('frozen protocol and unchanged runner digest');
for (const file of record.execution.files) {
  const bytes = readFileSync(resolve(repo, file.path)); assert.equal(bytes.length, file.bytes); assert.equal(sha(bytes), file.sha256);
}
groups.push('five existing text/image source identities independently rehashed');
assert.equal(sha(readFileSync(record.localEvidence.path)), record.localEvidence.sha256);
groups.push('local evidence digest matches');
assert.deepEqual(record.result, record.execution.result);
assert.equal(record.result.coordinateProjectionArithmetic, 'PASS');
assert.equal(record.result.independentSpatialAccuracy, 'BLOCKED');
assert.equal(record.result.regionalCompatibility, 'unconfirmed');
for (const cap of ['nav', 'staticCollision', 'staticLOS', 'dynamicOcclusion']) assert.equal(record.result[cap], 'NOT RUN');
assert.ok(record.compatibilityProposal.current.every(c => c.level === 'unconfirmed')); groups.push('capabilities remain separated');
assert.equal(record.independenceAudit.validPointCorrespondences, 0);
assert.equal(record.execution.imageReferences.length, 8);
assert.ok(record.execution.imageReferences.every(r => r.worldPosition === null && r.validationEligible === false && r.trainingEligible === false));
assert.ok(['mean', 'median', 'max', 'p95'].every(key => record.execution.independentResiduals[key] === null)); groups.push('zero independent truth is not zero error');
let area = 0;
for (const r of record.execution.regions) {
  area += (r.bounds[2] - r.bounds[0]) * (r.bounds[3] - r.bounds[1]);
  assert.equal(r.sampleCount, r.insideCount); assert.equal(r.independentCorrespondences, 0);
  assert.equal(r.upperBoundPx.p95, null); assert.ok(r.upperBoundPx.max > 0);
}
assert.equal(record.coverage.coarseRectangleAreaPx2, area);
assert.equal(record.coverage.coarseRectangleImageFraction, area / 1024 ** 2);
for (const key of ['x', 'y', 'z']) assert.deepEqual(record.coverage.observedWorldExtent[key], [Math.min(...original.probes.map(p => p.input[key])), Math.max(...original.probes.map(p => p.input[key]))]);
groups.push('region totals, conditional bounds and descriptive coverage');
assert.equal(record.validation.uniqueRuntimeTests, 20);
assert.equal(record.validation.unitTests.passed + record.validation.existingRelevantTests.passed, 20);
assert.equal(record.distance.testCount, 1); assert.equal(record.distance.kindComparisons, 8); groups.push('test counts not inflated by reviewer rerun');
const localLinks = [...markdown.matchAll(/\]\(([^)]+)\)/g)].map(m => m[1]).filter(href => !/^https?:/.test(href));
for (const link of localLinks) assert.ok(existsSync(resolve(repo, 'docs', link.split('#')[0])), link);
for (const source of record.sources) if (source.path) assert.ok(existsSync(resolve(repo, source.path)), source.path);
groups.push(`${localLinks.length} local Markdown links and ${record.sources.filter(s => s.path).length} local source paths exist`);
assert.ok(!/765611\d{11}/.test(JSON.stringify(record)));
assert.ok(!/765611\d{11}/.test(markdown)); groups.push('new report excludes Steam identity literals');
assert.match(record.compatibilityProposal.levels.mismatched, /lower error bound/);
assert.match(record.compatibilityProposal.levels.unconfirmed, /e\+u>T alone is not mismatch/);
assert.match(markdown, /世界坐标测量误差传播/);
assert.match(markdown, /max\(0,e−u\)/); groups.push('uncertainty and mismatched-definition corrections verified');
console.log(JSON.stringify({status: 'PASS', groups: groups.length, checks: groups, scope: 'Static report and existing scratch-output review; no DEM/native/game resource execution'}));
